class_name BTSelector
extends BTNode

@export var children: Array[BTNode] = []

func tick(blackboard: Dictionary) -> int:
	for child in children:
		var status: int = child.tick(blackboard)
		if status == SUCCESS:
			return SUCCESS
		elif status == RUNNING:
			return RUNNING
		# FAILURE: continue to next child
	return FAILURE

class_name BTSequence
extends BTNode

@export var children: Array[BTNode] = []

func tick(blackboard: Dictionary) -> int:
	for child in children:
		var status: int = child.tick(blackboard)
		if status == FAILURE:
			return FAILURE
		elif status == RUNNING:
			return RUNNING
		# SUCCESS: continue to next child
	return SUCCESS

class_name BTInverter
extends BTNode

@export var child: BTNode = null

func tick(blackboard: Dictionary) -> int:
	var status: int = child.tick(blackboard)
	if status == SUCCESS:
		return FAILURE
	elif status == FAILURE:
		return SUCCESS
	else:  # RUNNING
		return RUNNING

class_name IsHealthy
extends BTAction

func tick(blackboard: Dictionary) -> int:
	if blackboard["health"] >= blackboard["healthy_threshold"]:
		return SUCCESS
	return FAILURE

